pub fn compute_spec_OFF_FRAME_MAPPING_guarantee(
  api_applied_lifecycle: Vehicle_Start_Readiness_Recovery_Supervisor::AppliedLifecycleSnapshot,
  api_authorization: Vehicle_Start_Readiness_Recovery_Supervisor::StartAuthorizationFacts,
  api_control_frame: Vehicle_Start_Readiness_Recovery_Supervisor::ControlFrame) -> bool
{
  (api_applied_lifecycle.nextMode == Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleMode::Off) &
    (api_control_frame.startEnable == Vehicle_Start_Readiness_Recovery_Supervisor::StartEnable::Inhibit) &
    (api_control_frame.parkingBrake == Vehicle_Start_Readiness_Recovery_Supervisor::ParkingBrakeCommand::Apply) &
    (api_control_frame.powerDisposition == Vehicle_Start_Readiness_Recovery_Supervisor::PowerDisposition::Isolate) &
    (api_control_frame.selfTestCommand == Vehicle_Start_Readiness_Recovery_Supervisor::SelfTestCommand::None) &
    (api_control_frame.lifecycleMode == Vehicle_Start_Readiness_Recovery_Supervisor::ControlLifecycleMode::Off) &
    ((api_applied_lifecycle.reason == Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleReason::RecoveryCompleted) &
      (api_control_frame.status == Vehicle_Start_Readiness_Recovery_Supervisor::SupervisoryStatus::RecoveredAwaitFreshStart) |
      (api_applied_lifecycle.reason != Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleReason::RecoveryCompleted) &
        (api_authorization.decision == Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyInvalid) &
        (api_control_frame.status == Vehicle_Start_Readiness_Recovery_Supervisor::SupervisoryStatus::StartBlockedInvalid) |
      (api_applied_lifecycle.reason != Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleReason::RecoveryCompleted) &
        (api_authorization.decision != Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyInvalid) &
        (api_authorization.decision == Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyNotReady) &
        (api_control_frame.status == Vehicle_Start_Readiness_Recovery_Supervisor::SupervisoryStatus::StartBlockedNotReady) |
      (api_applied_lifecycle.reason != Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleReason::RecoveryCompleted) &
        (api_authorization.decision != Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyInvalid) &
        (api_authorization.decision != Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyNotReady) &
        api_authorization.conflict &
        (api_control_frame.status == Vehicle_Start_Readiness_Recovery_Supervisor::SupervisoryStatus::RequestConflict) |
      (api_applied_lifecycle.reason != Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleReason::RecoveryCompleted) &
        (api_authorization.decision != Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyInvalid) &
        (api_authorization.decision != Vehicle_Start_Readiness_Recovery_Supervisor::StartDecision::DenyNotReady) &
        (api_authorization.conflict == false) &
        (api_control_frame.status == Vehicle_Start_Readiness_Recovery_Supervisor::SupervisoryStatus::Idle)) |
    (api_applied_lifecycle.nextMode != Vehicle_Start_Readiness_Recovery_Supervisor::LifecycleMode::Off)
}

